/**
 * Generate a random todo via the API for E2E testing.
 *
 * Prepares random todo data using the prepare function, then calls the creation endpoint to create a new todo for the authenticated member. The todo is marked as incomplete by default and includes randomized title, description, start date, and due date.
 *
 * All optional properties (description, start_date, due_date) support input override through DeepPartial, allowing test customization while providing sensible defaults for automatic generation. The created todo includes all fields populated by the server including the generated UUID, timestamps, member relation, and empty edit histories array.
 */
export async function generate_random_todo_app_member_todos_create(
  connection: api.IConnection,
  props: {
    body?: DeepPartial<ITodoAppTodo.ICreate>;
  },
): Promise<ITodoAppTodo> {
  const prepared: ITodoAppTodo.ICreate = prepare_random_todo_app_todo(
    props.body,
  );
  const result: ITodoAppTodo = await api.functional.todoApp.member.todos.create(
    connection,
    {
      body: prepared,
    },
  );
  return result;
}

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import { IEntity } from "@ORGANIZATION/PROJECT-api/lib/structures/IEntity";
import type { ITodoAppGuest } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppGuest";
import { DeepPartial } from "@ORGANIZATION/PROJECT-api/lib/typings/DeepPartial";
import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import { randint } from "tstl";
import typia, { tags } from "typia";

import { authorize_guest_join } from "../../../authorize/authorize_guest_join";
import { authorize_guest_refresh } from "../../../authorize/authorize_guest_refresh";

/**
 * Test successful guest account registration with a unique device fingerprint.
 *
 * Validates the complete guest registration flow including device fingerprint submission, session context capture, and JWT token generation. Ensures that the system correctly creates a guest account identified by the unique device fingerprint and returns proper authentication credentials.
 *
 * Special attention is given to verifying token lifetimes - access tokens should be short-lived for security while refresh tokens provide longer session continuity. The session metadata (IP address, href, referrer) must be captured for audit and security monitoring purposes.
 *
 * 1. Generate unique device fingerprint and session context data.
 * 2. Register guest account using authorize_guest_join utility.
 * 3. Validate response structure contains guest ID and authorization tokens.
 * 4. Verify token expiration timestamps reflect appropriate lifetimes.
 * 5. Confirm all session metadata fields are properly captured.
 */
export async function test_api_guest_join_with_unique_device_fingerprint(
  connection: api.IConnection,
): Promise<void> {
  // 1. Prepare guest registration data with unique device fingerprint
  const deviceFingerprint = RandomGenerator.alphaNumeric(32);
  const href = typia.random<string & tags.Format<"uri">>();
  const referrer = typia.random<string & tags.Format<"uri">>();
  const ip = typia.random<string & tags.Format<"ipv4">>();
  // 2. Create guest connection and register
  const guestConnection: api.IConnection = { host: connection.host };
  const authorized = await authorize_guest_join(guestConnection, {
    body: {
      device_fingerprint: deviceFingerprint,
      href: href,
      referrer: referrer,
      ip: ip,
    } satisfies ITodoAppGuest.IJoin,
  });
  typia.assert(authorized);
  // 3. Validate refresh token lifetime is longer than access token lifetime
  const accessExpiration = new Date(authorized.token.expired_at).getTime();
  const refreshExpiration = new Date(
    authorized.token.refreshable_until,
  ).getTime();
  TestValidator.predicate("refresh token expires after access token", () => {
    return refreshExpiration > accessExpiration;
  });
}

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import { IEntity } from "@ORGANIZATION/PROJECT-api/lib/structures/IEntity";
import type { ITodoAppGuest } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppGuest";
import { DeepPartial } from "@ORGANIZATION/PROJECT-api/lib/typings/DeepPartial";
import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import { randint } from "tstl";
import typia, { tags } from "typia";

import { authorize_guest_join } from "../../../authorize/authorize_guest_join";
import { authorize_guest_refresh } from "../../../authorize/authorize_guest_refresh";

/**
 * Test guest registration with existing device fingerprint.
 *
 * Validates the system's handling of duplicate device fingerprint scenarios during guest registration. First registers a guest account with a specific device fingerprint, then attempts to register again with the same fingerprint. The system should recognize the existing guest and return the same guest ID with new or existing authentication tokens.
 *
 * This ensures that anonymous users returning with the same device are recognized as the same guest account, maintaining data consistency and preventing duplicate guest accounts. The test verifies that the guest ID remains consistent across both registration attempts.
 *
 * 1. Register first guest with a specific device fingerprint and capture the guest ID.
 * 2. Attempt second registration with the identical device fingerprint.
 * 3. Verify the second response returns the same guest ID as the first registration.
 * 4. Validate both responses contain proper authentication tokens with correct structure.
 */
export async function test_api_guest_join_with_existing_device_fingerprint(
  connection: api.IConnection,
): Promise<void> {
  // Generate a unique device fingerprint for this test
  const deviceFingerprint = RandomGenerator.alphaNumeric(32);
  // Create session metadata for the registration
  const sessionData = {
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
    ip: typia.random<string & tags.Format<"ipv4">>(),
  } satisfies Omit<ITodoAppGuest.IJoin, "device_fingerprint">;
  // 1. First registration - create guest account
  const firstConnection: api.IConnection = { host: connection.host };
  const firstGuest = await authorize_guest_join(firstConnection, {
    body: {
      device_fingerprint: deviceFingerprint,
      ...sessionData,
    } satisfies ITodoAppGuest.IJoin,
  });
  typia.assert(firstGuest);
  // 2. Second registration - attempt with same device fingerprint
  const secondConnection: api.IConnection = { host: connection.host };
  const secondGuest = await authorize_guest_join(secondConnection, {
    body: {
      device_fingerprint: deviceFingerprint,
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
      ip: typia.random<string & tags.Format<"ipv4">>(),
    } satisfies ITodoAppGuest.IJoin,
  });
  typia.assert(secondGuest);
  // 3. Verify same guest ID is returned (no duplicate account created)
  TestValidator.equals(
    "guest ID should match existing account",
    secondGuest.id,
    firstGuest.id,
  );
}

import api from "@ORGANIZATION/PROJECT-api";
